head.script:
    scwin.onpageload = function() {

    };

    scwin.onpageunload = function() {

    };



   scwin.trigger1_onclick = function()
    {
        var winObj = {
            title : 'test',
            src : "a.xml",
            windowTitle : "windowTitle",
            windowId : "windowId",
            frameMode : "wframe",
			defaultWidth : "200",
            defaultHeight : "200"
        }
        wc1.createWindow( winObj );
        winObj.windowId = "windowId1";
        winObj.defaultWidth = "400";
        winObj.defaultHeight = "400";
        wc1.createWindow( winObj );
        wc1.setArrangeWindows("cascade");
    };
	scwin.checkVal = function() {
		return WebSquare.wUnit.getDomById($p.id + 'wc1_window').children[1].getAttribute('id') == $p.id+'wc1_subWindow1';
	}
	scwin.unitTest = function() {
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
		WebSquare.wUnit.addCommand("pause", "800");
		//WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('wc1_subWindow1_close').click()");
		//WebSquare.wUnit.addCommand("pause", "400");
		//WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('wc1_subWindow0_close').click()");
		//WebSquare.wUnit.addCommand("pause", "400");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wc1_subWindow1').close()");
		WebSquare.wUnit.addCommand("pause", "400");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wc1_subWindow0').close()");
		WebSquare.wUnit.addCommand("pause", "400");		
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
		WebSquare.wUnit.addCommand("pause", "400");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
		WebSquare.wUnit.addCommand("pause", "500");
		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest();
